  Widget _buildTextField(bool isDark, IconData icon, String hint, Color accent, Color textColor, Color hintColor, {int maxLines = 1}) {
    return Container(
      // margin: const EdgeInsets.only(bottom: 16), // Handled by parent spacing in Flutter > 3.24 or use SizedBox
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF1E293B).withValues(alpha: 0.5) : const Color(0xFFF8FAFC),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.transparent),
      ),
      child: Row(
        crossAxisAlignment: maxLines > 1 ? CrossAxisAlignment.start : CrossAxisAlignment.center,
        children: [
           Padding(
             padding: EdgeInsets.only(top: maxLines > 1 ? 4 : 0),
             child: Icon(icon, color: accent.withValues(alpha: 0.8), size: 20),
           ),
           const SizedBox(width: 16),
           Expanded(
             child: TextField(
               maxLines: maxLines,
               style: TextStyle(color: textColor, fontWeight: FontWeight.w500),
               decoration: InputDecoration(
                 isDense: true,
                 hintText: hint,
                 hintStyle: TextStyle(color: hintColor),
                 border: InputBorder.none,
                 contentPadding: EdgeInsets.zero,
               ),
             ),
           ),
        ],
      ),
    );
  }

  Widget _buildBottomNavBar(BuildContext context, bool isDark) {
    final theme = Theme.of(context);
    final surfaceColor = theme.colorScheme.surface; // Or custom
    // For this specific screen, we might want to replicate the same nav bar style as others
    final borderColor = isDark ? const Color(0xFF334155) : const Color(0xFFE2E8F0);
    final primaryOrange = const Color(0xFFFF5722);
    // Use slightly different colors for the nav bar in this specific design if requested, 
    // but better to keep consistency with other screens

    return Container(
      padding: const EdgeInsets.only(top: 12, bottom: 24),
      decoration: BoxDecoration(
        color: surfaceColor.withValues(alpha: 0.9),
        border: Border(top: BorderSide(color: borderColor)),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.05),
            blurRadius: 10,
            offset: const Offset(0, -4),
          ),
        ],
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceAround,
        crossAxisAlignment: CrossAxisAlignment.end,
        children: [
          _buildNavItem(context, Icons.home, 'Home', false, isDark, 
             onTap: () => Navigator.of(context).pushReplacement(
                PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const HomeScreen(),
                    transitionDuration: Duration.zero,
                )
             )
          ),
          _buildNavItem(context, Icons.calendar_today, 'Events', false, isDark,
             onTap: () => Navigator.of(context).pushReplacement(
                PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const EventsScreen(),
                    transitionDuration: Duration.zero,
                )
             )
          ),

          // Floating Action Button - Active Here? or just same style?
          // In the design, it's just the center button.
          Transform.translate(
            offset: const Offset(0, -24),
            child: Container(
              width: 56,
              height: 56,
              decoration: BoxDecoration(
                color: primaryOrange,
                shape: BoxShape.circle,
                boxShadow: [
                  BoxShadow(
                    color: primaryOrange.withValues(alpha: 0.4),
                    blurRadius: 10,
                    offset: const Offset(0, 4),
                  ),
                ],
              ),
              child: const Icon(Icons.add, color: Colors.white, size: 28),
            ),
          ),

          _buildNavItem(context, Icons.leaderboard, 'Ranking', false, isDark,
             onTap: () => Navigator.of(context).pushReplacement(
                PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const RankingScreen(),
                    transitionDuration: Duration.zero,
                )
             )
          ),
          _buildNavItem(context, Icons.person, 'Profile', false, isDark,
             onTap: () => Navigator.of(context).pushReplacement(
                PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const ProfileScreen(),
                    transitionDuration: Duration.zero,
                )
             )
          ),
        ],
      ),
    );
  }

  Widget _buildNavItem(BuildContext context, IconData icon, String label, bool isActive, bool isDark, {VoidCallback? onTap}) {
    final secondaryText = isDark ? const Color(0xFF94A3B8) : const Color(0xFF64748B);
    final primaryOrange = const Color(0xFFFF5722);
    final color = isActive ? primaryOrange : secondaryText;

    return GestureDetector(
      onTap: onTap,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, color: color),
          const SizedBox(height: 4),
          Text(
            label,
            style: TextStyle(
              color: color,
              fontSize: 10,
              fontWeight: FontWeight.w500,
            ),
          ),
        ],
      ),
    );
  }
}


