          _buildNavItem(context, Icons.leaderboard, 'Ranking', false, isDark,
             onTap: () => Navigator.of(context).pushReplacement(
                PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const RankingScreen(),
                    transitionDuration: Duration.zero,
                )
             )
          ),
          // Profile is Active because we are editing profile
          _buildNavItem(context, Icons.person, 'Profile', true, isDark,
             onTap: () => Navigator.of(context).pushReplacement(
                PageRouteBuilder(
                    pageBuilder: (_, __, ___) => const ProfileScreen(),
                    transitionDuration: Duration.zero,
                )
             )
          ),
        ],
      ),
    );
  }

  Widget _buildNavItem(BuildContext context, IconData icon, String label, bool isActive, bool isDark, {VoidCallback? onTap}) {
    final theme = Theme.of(context);
    final primaryOrange = theme.colorScheme.primary;
    final secondaryText = isDark ? const Color(0xFF9CA3AF) : const Color(0xFF6B7280);

    final color = isActive ? primaryOrange : secondaryText;

    return GestureDetector(
      onTap: onTap,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, color: color),
          const SizedBox(height: 4),
          Text(
            label,
            style: TextStyle(
              color: color,
              fontSize: 10,
              fontWeight: FontWeight.w500,
            ),
          ),
        ],
      ),
    );
  }
}


