  Widget _buildCalendarGrid(BuildContext context, Color textColor, Color secondaryColor, Color primaryColor) {
    final daysInMonth = DateUtils.getDaysInMonth(_focusedDay.year, _focusedDay.month);
    final firstDayOfMonth = DateTime(_focusedDay.year, _focusedDay.month, 1);
    final firstWeekday = firstDayOfMonth.weekday % 7; // 0 for Sunday, etc. based on column alignment

    List<Widget> days = [];

    // Empty slots for previous month
    for (int i = 0; i < firstWeekday; i++) {
         days.add(const SizedBox(width: 36, height: 48)); // Placeholder size
    }

    // Current month days
    for (int i = 1; i <= daysInMonth; i++) {
        final date = DateTime(_focusedDay.year, _focusedDay.month, i);
        bool isSelected = DateUtils.isSameDay(date, _selectedDay);
        bool isToday = DateUtils.isSameDay(date, DateTime.now());
        // Dummy event logic (random-ish but consistent)
        bool hasEvent = (i % 5 == 0) || (i % 7 == 3); 

        days.add(GestureDetector(
          onTap: () {
            setState(() {
              _selectedDay = date;
            });
          },
          child: _buildCalendarDay(i.toString(), isSelected ? Colors.white : textColor, isSelected, hasEvent, isToday, primaryColor: primaryColor)
        ));
    }

    return Wrap(
      spacing: 6,
      runSpacing: 4,
      alignment: WrapAlignment.start, 
      children: days.map((w) => SizedBox(width: 40, child: Center(child: w))).toList(),
    );
  }

  Widget _buildCalendarDay(String day, Color color, bool isSelected, bool hasEvent, bool isToday, {Color? primaryColor}) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Container(
          width: 36,
          height: 36,
          alignment: Alignment.center,
          decoration: isSelected
              ? BoxDecoration(
                  color: primaryColor,
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: primaryColor!.withValues(alpha: 0.3),
                      blurRadius: 10,
                      offset: const Offset(0, 4),
                    ),
                  ],
                )
              : isToday ? BoxDecoration(
                  border: Border.all(color: primaryColor!),
                  shape: BoxShape.circle,
              ) : null,
          child: Text(
            day,
            style: TextStyle(
              fontSize: 14,
              fontWeight: isSelected ? FontWeight.bold : FontWeight.w500,
              color: color,
            ),
          ),
        ),
        const SizedBox(height: 4),
        if (hasEvent && !isSelected)
            Container(
              width: 4,
              height: 4,
              decoration: BoxDecoration(
                color: primaryColor,
                shape: BoxShape.circle,
              ),
            )
        else
             const SizedBox(height: 4), // Maintains height alignment
      ],
    );
  }

