import 'package:flutter/material.dart';
import 'splash_screen.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    // Define Colors
    const primaryOrange = Color(0xFFFF5722);

    // Dark Theme Colors
    const darkBackground = Color(0xFF191B1F);
    const darkInputFill = Color(0xFF25282B);
    const darkInputBorder = Color(0xFF383838);

    // Light Theme Colors (Inferred opposites)
    const lightBackground = Color(0xFFF5F5F5); // Light grey/white
    const lightInputFill = Color(0xFFFFFFFF); // White inputs
    const lightInputBorder = Color(0xFFE0E0E0);

    return MaterialApp(
      title: 'Tuni Dev',
      debugShowCheckedModeBanner: false,
      themeMode: ThemeMode.system, // Adapts to system setting

      // Light Theme Definition
      theme: ThemeData(
        brightness: Brightness.light,
        scaffoldBackgroundColor: lightBackground,
        colorScheme: ColorScheme.light(
          primary: primaryOrange,
          surface: lightInputFill,
          onSurface: Colors.black, // Text Color
          outline: lightInputBorder,
        ),
        useMaterial3: true,
      ),

      // Dark Theme Definition
      darkTheme: ThemeData(
        brightness: Brightness.dark,
        scaffoldBackgroundColor: darkBackground,
        colorScheme: ColorScheme.dark(
          primary: primaryOrange,
          surface: darkInputFill,
          onSurface: Colors.white, // Text Color
          outline: darkInputBorder,
        ),
        useMaterial3: true,
      ),

      home: const SplashScreen(),
    );
  }
}


