import 'dart:async';
import 'dart:math';
import 'package:flutter/widgets.dart';
import '../data/face_data.dart';
import 'face_messenger.dart';

class CursorController extends ChangeNotifier {
  final FaceMessenger _messenger;

  Offset _cursorPosition = Offset.zero;
  Offset get cursorPosition => _cursorPosition;

  bool _isClicking = false;
  bool get isClicking => _isClicking;

  final StreamController<void> _clickStreamController = StreamController<void>.broadcast();
  Stream<void> get clickStream => _clickStreamController.stream;

  // Calibration & Debug
  double _zeroYaw = 0.0;
  double _zeroPitch = 0.0;

  double _currentYaw = 0.0;
  double _currentPitch = 0.0;

  double get rawYaw => _currentYaw;
  double get rawPitch => _currentPitch;

  // Settings
  bool invertX = false; // Default to Direct (Face Right -> Cursor Right)
  bool invertY = false;
  bool swapXY = true; // Default to Portrait Mode (Fixes "Right -> Down")
  double sensitivity = 800.0;

  // Public Notifier for UI status updates
  final ValueNotifier<bool> isClickingNotifier = ValueNotifier(false);
  final ValueNotifier<bool> isFaceDetectedNotifier = ValueNotifier(false);
  Timer? _lossTimer;

  // Screen Size (must be updated from UI)
  Size _screenSize = Size.zero;

  final OneEuroFilter _filterX = OneEuroFilter(minCutoff: 1.0, beta: 0.08);
  final OneEuroFilter _filterY = OneEuroFilter(minCutoff: 1.0, beta: 0.08);

  StreamSubscription? _subscription;

  bool _stopped = false;

  CursorController(this._messenger);

  void start() {
    _stopped = false;
    _isClicking = false;
    _filterX.reset();
    _filterY.reset();
    // EventChannel.listen triggers onListen in Kotlin which calls startCamera()
    // Do NOT call _messenger.startCamera() separately — it causes double-start
    _subscription = _messenger.faceDataStream.listen(_onFaceData);
  }

  void stop() {
    _stopped = true;
    // Cancelling the subscription triggers onCancel in Kotlin which stops camera
    // Do NOT call _messenger.stopCamera() separately
    _subscription?.cancel();
    _subscription = null;
    _lossTimer?.cancel();
    // Do NOT dispose notifiers here - they may be restarted
    // Only dispose in dispose()
  }

  void setInvertX(bool value) {
    invertX = value;
    notifyListeners();
  }

  void setInvertY(bool value) {
    invertY = value;
    notifyListeners();
  }

  void setSwapXY(bool value) {
    swapXY = value;
    notifyListeners();
  }

  void setSensitivity(double value) {
    sensitivity = value;
    notifyListeners();
  }

  void updateScreenSize(Size size) {
    _screenSize = size;
    // Reset cursor to center if it's the first time
    if (_cursorPosition == Offset.zero) {
      _cursorPosition = Offset(size.width / 2, size.height / 2);
    }
  }

  void calibrate() {
    _pendingCalibration = true;
  }

  bool _pendingCalibration = false;

  void _onFaceData(FaceData data) {
    // Guard: ignore data after stop/dispose
    if (_stopped) return;

    // Face Detected logic
    if (!isFaceDetectedNotifier.value) {
      isFaceDetectedNotifier.value = true;
    }
    _lossTimer?.cancel();
    _lossTimer = Timer(const Duration(milliseconds: 500), () {
      isFaceDetectedNotifier.value = false;
    });

    // Update debug values
    _currentYaw = data.yaw;
    _currentPitch = data.pitch;

    if (_pendingCalibration) {
      _zeroYaw = data.yaw;
      _zeroPitch = data.pitch;
      _pendingCalibration = false;
    }

    // click detection (both eyes closed)
    // EAR < 0.15 = eyes definitely closed
    debugPrint("EAR: L=${data.leftEyeOpen.toStringAsFixed(3)} R=${data.rightEyeOpen.toStringAsFixed(3)}");
    bool clicking = data.leftEyeOpen < 0.15 && data.rightEyeOpen < 0.15;
    if (clicking != _isClicking) {
      _isClicking = clicking;
      isClickingNotifier.value = clicking;
      notifyListeners();
      if (_isClicking) {
        debugPrint("CLICK REGISTERED!");
        _clickStreamController.add(null);
      }
    }

    // Movement logic
    double deltaYaw = data.yaw - _zeroYaw;
    double deltaPitch = data.pitch - _zeroPitch;

    // Deadzone to reduce jitter
    if (deltaYaw.abs() < 0.005) deltaYaw = 0.0;
    if (deltaPitch.abs() < 0.005) deltaPitch = 0.0;

    // Apply Settings
    // IF SWAPPED (Portrait Mode fix):

    double inputX, inputY;

    if (swapXY) {
       // Swap the inputs: Pitch drives X, Yaw drives Y
       inputX = deltaPitch;
       inputY = deltaYaw;
    } else {
       inputX = deltaYaw;
       inputY = deltaPitch;
    }

    // Apply sensitivity & Inversion
    double moveX = inputX * sensitivity;
    if (invertX) moveX = -moveX;

    double moveY = inputY * sensitivity;
    if (invertY) moveY = -moveY;

    double rawX = _screenSize.width / 2 + moveX;
    double rawY = _screenSize.height / 2 + moveY;

    // Filter
    double timestamp = DateTime.now().millisecondsSinceEpoch / 1000.0;
    double x = _filterX.filter(rawX, timestamp);
    double y = _filterY.filter(rawY, timestamp);

    // Clamp to screen
    if (_screenSize != Size.zero) {
      x = x.clamp(0.0, _screenSize.width);
      y = y.clamp(0.0, _screenSize.height);
    }

    _cursorPosition = Offset(x, y);

    // Debug: Log position updates (comment out in production)
    // debugPrint("📍 Cursor: ($x, $y)");

    notifyListeners();
  }

  @override
  void dispose() {
    _clickStreamController.close();
    stop();
    isClickingNotifier.dispose();
    isFaceDetectedNotifier.dispose();
    super.dispose();
  }
}

// Simple OneEuroFilter implementation for Dart
class OneEuroFilter {
  double _minCutoff = 1.0;
  double _beta = 0.0;
  double _dCutoff = 1.0;

  double? _prevValue;
  double? _prevDerivative;
  double? _prevTimestamp;

  OneEuroFilter({double minCutoff = 1.0, double beta = 0.007, double dCutoff = 1.0}) {
    _minCutoff = minCutoff;
    _beta = beta;
    _dCutoff = dCutoff;
  }

  void reset() {
    _prevValue = null;
    _prevDerivative = null;
    _prevTimestamp = null;
  }

  double filter(double value, double timestamp) {
    if (_prevTimestamp == null || _prevValue == null || _prevDerivative == null) {
      _prevValue = value;
      _prevDerivative = 0.0;
      _prevTimestamp = timestamp;
      return value;
    }

    double dt = timestamp - _prevTimestamp!;

    // Compute alpha for the derivative filter
    double alphaD = _smoothingFactor(dt, _dCutoff);

    // Compute derivative
    double derivative = (value - _prevValue!) / dt;
    double dxHat = _exponentialSmoothing(alphaD, derivative, _prevDerivative!);

    // Compute alpha for the value filter
    double cutoff = _minCutoff + _beta * dxHat.abs();
    double alpha = _smoothingFactor(dt, cutoff);

    // Filter value
    double xHat = _exponentialSmoothing(alpha, value, _prevValue!);

    _prevValue = xHat;
    _prevDerivative = dxHat;
    _prevTimestamp = timestamp;

    return xHat;
  }

  double _smoothingFactor(double dt, double cutoff) {
    double r = 2 * pi * cutoff * dt;
    return r / (r + 1);
  }

  double _exponentialSmoothing(double alpha, double x, double xPrev) {
    return alpha * x + (1 - alpha) * xPrev;
  }
}


import 'package:flutter/services.dart';
import 'package:flutter/foundation.dart';
import '../data/face_data.dart';

class FaceMessenger {
  static const MethodChannel _methodChannel = MethodChannel('face_mesh/control');
  static const EventChannel _eventChannel = EventChannel('face_mesh/data');

  Stream<FaceData>? _faceDataStream;

  Stream<FaceData> get faceDataStream {
    _faceDataStream ??= _eventChannel.receiveBroadcastStream().map((event) {
      if (event is Map) {
        return FaceData.fromMap(event);
      } else {
        // Fallback or empty
        return FaceData(yaw: 0, pitch: 0, roll: 0, leftEyeOpen: 0, rightEyeOpen: 0);
      }
    });
    return _faceDataStream!;
  }

  Future<void> startCamera() async {
    try {
      await _methodChannel.invokeMethod('startCamera');
    } on PlatformException catch (e) {
      debugPrint("Failed to start camera: '${e.message}'.");
    }
  }

  Future<void> stopCamera() async {
    try {
      await _methodChannel.invokeMethod('stopCamera');
    } on PlatformException catch (e) {
      debugPrint("Failed to stop camera: '${e.message}'.");
    }
  }
}


import 'dart:async';
import 'package:flutter/foundation.dart';

/// Detects user inactivity and notifies listeners when the user has been idle
/// for a specified duration (default: 5 seconds).
class InactivityDetector extends ChangeNotifier {
  Timer? _timer;
  bool _isIdle = false;
  final Duration inactivityDuration;

  InactivityDetector({this.inactivityDuration = const Duration(seconds: 5)});

  /// Returns true if the user has been idle for the specified duration
  bool get isIdle => _isIdle;

  /// Call this method whenever the user interacts with the screen
  /// (touch, pointer down, pointer move, etc.)
  void onUserInteraction() {
    // If we were idle, we're now active
    if (_isIdle) {
      _isIdle = false;
      notifyListeners();
    }

    // Cancel any existing timer
    _timer?.cancel();

    // Start a new timer
    _timer = Timer(inactivityDuration, () {
      _isIdle = true;
      notifyListeners();
    });
  }

  /// Reset the detector to non-idle state and cancel the timer
  void reset() {
    _timer?.cancel();
    if (_isIdle) {
      _isIdle = false;
      notifyListeners();
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }
}


import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter/gestures.dart';
import '../logic/cursor_controller.dart';
import '../logic/inactivity_detector.dart';

/// Overlay widget that displays the cursor and automatically shows/hides
/// based on user inactivity.
class CursorOverlay extends StatefulWidget {
  final CursorController controller;
  final InactivityDetector inactivityDetector;
  final Widget child;

  const CursorOverlay({
    super.key,
    required this.controller,
    required this.inactivityDetector,
    required this.child,
  });

  @override
  State<CursorOverlay> createState() => _CursorOverlayState();
}

class _CursorOverlayState extends State<CursorOverlay> {
  bool _showCursor = false;
  StreamSubscription<void>? _clickSubscription;
  bool _isSimulatingTap = false; // Prevent event loop
  Timer? _scrollTimer;
  double? _currentScrollDirection; // Track scroll direction to prevent spam

  @override
  void initState() {
    super.initState();
    widget.inactivityDetector.addListener(_onIdleStateChanged);
    widget.controller.addListener(_onCursorPositionChanged);
    // Note: Screen size is set in didChangeDependencies() below
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Update screen size when dependencies change
    final size = MediaQuery.of(context).size;
    widget.controller.updateScreenSize(size);
  }

  @override
  void dispose() {
    widget.inactivityDetector.removeListener(_onIdleStateChanged);
    widget.controller.removeListener(_onCursorPositionChanged);
    _clickSubscription?.cancel();
    _scrollTimer?.cancel();
    super.dispose();
  }

  void _onIdleStateChanged() {
    // Don't hide cursor if we're simulating a tap
    if (_isSimulatingTap) return;

    final isIdle = widget.inactivityDetector.isIdle;

    if (isIdle && !_showCursor) {
      // User has been idle for 5 seconds -> Show cursor and start tracking
      widget.controller.start();
      setState(() => _showCursor = true);

      // Listen to click events
      _clickSubscription = widget.controller.clickStream.listen((_) {
        _simulateTapAtCursorPosition();
      });
    } else if (!isIdle && _showCursor) {
      // User touched the screen -> Hide cursor and stop tracking
      _clickSubscription?.cancel();
      _clickSubscription = null;
      widget.controller.stop();
      setState(() => _showCursor = false);
    }
  }

  void _simulateTapAtCursorPosition() async {
    final position = widget.controller.cursorPosition;

    debugPrint("🎯 SIMULATING TAP at position: $position");

    // Set flag to prevent hiding cursor during simulation
    _isSimulatingTap = true;

    // Create a unique pointer ID for this tap sequence
    final pointerId = DateTime.now().millisecondsSinceEpoch % 10000;
    final now = DateTime.now().millisecondsSinceEpoch;

    // 1. Add pointer (device detection)
    final pointerAddedEvent = PointerAddedEvent(
      pointer: pointerId,
      position: position,
      timeStamp: Duration(milliseconds: now),
    );
    GestureBinding.instance.handlePointerEvent(pointerAddedEvent);

    await Future.delayed(const Duration(milliseconds: 10));

    // 2. Pointer down event
    final pointerDownEvent = PointerDownEvent(
      pointer: pointerId,
      position: position,
      timeStamp: Duration(milliseconds: now + 10),
      pressure: 1.0,
      pressureMin: 0.0,
      pressureMax: 1.0,
    );

    GestureBinding.instance.handlePointerEvent(pointerDownEvent);
    debugPrint("✅ Dispatched PointerDown at $position");

    // 3. Wait a bit then dispatch pointer up
    await Future.delayed(const Duration(milliseconds: 100));

    final pointerUpEvent = PointerUpEvent(
      pointer: pointerId,
      position: position,
      timeStamp: Duration(milliseconds: now + 110),
    );

    GestureBinding.instance.handlePointerEvent(pointerUpEvent);
    debugPrint("✅ Dispatched PointerUp at $position");

    // 4. Remove pointer
    await Future.delayed(const Duration(milliseconds: 10));

    final pointerRemovedEvent = PointerRemovedEvent(
      pointer: pointerId,
      position: position,
      timeStamp: Duration(milliseconds: now + 120),
    );
    GestureBinding.instance.handlePointerEvent(pointerRemovedEvent);

    // Reset flag after a short delay
    await Future.delayed(const Duration(milliseconds: 200));
    _isSimulatingTap = false;

    debugPrint("✅ Tap sequence complete");
  }

  void _onCursorPositionChanged() {
    if (!_showCursor) return;

    final position = widget.controller.cursorPosition;
    final screenHeight = MediaQuery.of(context).size.height;

    const edgeZone = 100.0; // pixels from edge to trigger scroll
    const scrollSpeed = 10.0; // pixels per frame

    // Check if cursor is in top or bottom edge zone
    if (position.dy < edgeZone) {
      // Cursor near top - scroll up
      _startScrolling(-scrollSpeed);
    } else if (position.dy > screenHeight - edgeZone) {
      // Cursor near bottom - scroll down
      _startScrolling(scrollSpeed);
    } else {
      // Cursor in safe zone - stop scrolling
      _stopScrolling();
    }
  }

  void _startScrolling(double delta) {
    // Only restart timer if direction changed or not already scrolling
    if (_currentScrollDirection == delta && _scrollTimer != null && _scrollTimer!.isActive) {
      return; // Already scrolling in this direction
    }

    // Cancel existing timer
    _scrollTimer?.cancel();
    _currentScrollDirection = delta;

    // Start new scroll timer
    _scrollTimer = Timer.periodic(const Duration(milliseconds: 50), (timer) {
      _performScroll(delta);
    });
  }

  void _stopScrolling() {
    _scrollTimer?.cancel();
    _scrollTimer = null;
    _currentScrollDirection = null;
  }

  void _performScroll(double delta) {
    // Instead of looking for a ScrollController, we simulate a Scroll Event (Mouse Wheel)
    // This works better because it finds the Scrollable underneath the cursor/center.

    final centerPos = Offset(
      MediaQuery.of(context).size.width / 2,
      MediaQuery.of(context).size.height / 2
    );

    // Create a pointer scroll event
    final scrollEvent = PointerScrollEvent(
      position: centerPos, // Send event to center of screen (usually safe for lists)
      scrollDelta: Offset(0, delta),
      kind: PointerDeviceKind.mouse,
    );

    // Dispatch the event
    GestureBinding.instance.handlePointerEvent(scrollEvent);
  }

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        widget.child,
        if (_showCursor)
          AnimatedBuilder(
            animation: widget.controller,
            builder: (context, _) {
              final pos = widget.controller.cursorPosition;
              final isClicking = widget.controller.isClicking;

              return Positioned(
                left: pos.dx - 20,
                top: pos.dy - 20,
                child: IgnorePointer(
                  child: Stack(
                    alignment: Alignment.center,
                    children: [
                      // Outer ring for visibility over images
                      Container(
                        width: isClicking ? 35 : 40,
                        height: isClicking ? 35 : 40,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          border: Border.all(
                            color: Colors.white.withValues(alpha: 0.8),
                            width: 2,
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: Colors.black.withValues(alpha: 0.3),
                              blurRadius: 8,
                              spreadRadius: 2,
                            ),
                          ],
                        ),
                      ),
                      // Inner gradient cursor
                      AnimatedContainer(
                        duration: const Duration(milliseconds: 100),
                        width: isClicking ? 25 : 30,
                        height: isClicking ? 25 : 30,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          gradient: RadialGradient(
                            colors: [
                              Colors.blueAccent.withValues(alpha: 0.9),
                              Colors.purpleAccent.withValues(alpha: 0.7),
                            ],
                          ),
                          boxShadow: [
                            BoxShadow(
                              color: isClicking 
                                  ? Colors.greenAccent.withValues(alpha: 0.6)
                                  : Colors.blueAccent.withValues(alpha: 0.4),
                              blurRadius: isClicking ? 20 : 15,
                              spreadRadius: isClicking ? 5 : 3,
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
      ],
    );
  }
}


import 'package:flutter/material.dart';
import '../logic/cursor_controller.dart';
