              Container(
                width: 8, height: 8,
                decoration: BoxDecoration(
                  color: isFaceDetected ? Colors.greenAccent : Colors.redAccent,
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(color: isFaceDetected ? Colors.greenAccent.withOpacity(0.5) : Colors.transparent, blurRadius: 6)
                  ]
