              ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildCalibrationTarget() {
    return GestureDetector(
      onTap: () {
        widget.controller.calibrate();
        _showFeedback("Center Calibrated!", Colors.greenAccent);
      },
